// NOTE: package README documents CSS primitives (`jx-*`) but does not list the
// React export names, so this uses the CSS layer + native elements. If
// @jinx-ui/react exports Input/Button/Tag, swap the tagged elements for them.
import { useCallback, useId, useRef, useState, type KeyboardEvent } from 'react';

export type TagPickerProps = {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  maxTags?: number;
  onChange: (tags: string[]) => void;
};

const normalize = (raw: string): string => raw.trim().replace(/\s+/g, ' ');

export default function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  maxTags,
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const hintId = useId();

  const isFull = maxTags !== undefined && tags.length >= maxTags;

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange(next);
    },
    [onChange],
  );

  const addTag = useCallback(() => {
    const tag = normalize(draft);
    if (!tag || isFull) return;
    const exists = tags.some((t) => t.toLowerCase() === tag.toLowerCase());
    if (exists) {
      setDraft('');
      return;
    }
    commit([...tags, tag]);
    setDraft('');
  }, [commit, draft, isFull, tags]);

  const removeTag = useCallback(
    (index: number) => {
      commit(tags.filter((_, i) => i !== index));
      inputRef.current?.focus();
    },
    [commit, tags],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag();
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      removeTag(tags.length - 1);
    }
  };

  return (
    <div
      className="jx-field"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2, 8px)' }}
    >
      <label className="jx-label" htmlFor={inputId}>
        {label}
      </label>

      <input
        id={inputId}
        ref={inputRef}
        className="jx-input"
        type="text"
        value={draft}
        placeholder={isFull ? 'Достигнут лимит тегов' : placeholder}
        disabled={isFull}
        aria-describedby={hintId}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={addTag}
      />

      <span id={hintId} className="jx-hint">
        Enter или запятая — добавить тег, Backspace в пустом поле — удалить последний
        {maxTags !== undefined ? ` (${tags.length}/${maxTags})` : null}
      </span>

      {tags.length > 0 ? (
        <ul
          className="jx-tag-list"
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: 'var(--jx-space-2, 8px)',
            margin: 0,
            padding: 0,
            listStyle: 'none',
          }}
        >
          {tags.map((tag, index) => (
            <li
              key={tag.toLowerCase()}
              className="jx-tag"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 'var(--jx-space-1, 4px)',
                borderRadius: 'var(--jx-radius, 4px)',
              }}
            >
              <span>{tag}</span>
              <button
                type="button"
                className="jx-button jx-button--ghost jx-button--icon"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(index)}
              >
                ×
              </button>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

